referenceSolutions.javascript:
export function orangesRotting(grid            )         {
  const cells=grid.map(row=>[...row]),rows=cells.length,cols=cells[0].length; const queue           =[]; let fresh=0,minutes=0; for(let r=0;r<rows;r++)for(let c=0;c<cols;c++) { if(cells[r][c]===1)fresh++; if(cells[r][c]===2)queue.push([r,c,0]); } for(let i=0;i<queue.length;i++) { const [r,c,time]=queue[i]; minutes=Math.max(minutes,time); for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) { const nr=r+dr,nc=c+dc; if(nr>=0&&nr<rows&&nc>=0&&nc<cols&&cells[nr][nc]===1) { cells[nr][nc]=2; fresh--;queue.push([nr,nc,time+1]); } } } return fresh===0?minutes:-1;
}

